head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setCellDisableEdit]<br/>inputType=\"custom\" 인 Column 의 특정 Body Cell 에서 텍스트 편집을 비활성화할 지 설정합니다.",
    "validation" : [
        "특정 Cell 의 inputType 속성값이 'autoComplete' 일때 동작합니다.",
        "setCellInputTypeCustom=false 일때 Column 의 typeGetter 속성이 설정되었거나 setCellInputTypeCustom=true 일때 동작합니다.",
        "rowIndex(필수) 파라미터로 텍스트 편집을 비활성화 하려는 Body Cell 의 Row 인덱스를 설정할 수 있어야 합니다.",
        "rowIndex(필수) 파라미터의 Row 인덱스는 0 부터 시작하며 GridView 에 표시된 Row 를 기준으로 인덱스가 설정됩니다.",
        "columnInfo(필수) 파라미터로 텍스트 편집을 비활성화 하려는 Body Cell 의 Column 인덱스를 설정할 수 있어야 합니다.",
        "columnInfo(필수) 파라미터의 Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",
        "disabled(필수) 파라미터에 true 설정 시 해당 Cell 의 입력창에서 텍스트 편집은 비활성화 되고 아이템 리스트를 통한 선택만 가능합니다.",
        "disabled(필수) 파라미터에 false 설정 시 해당 Cell 의 입력창에서 텍스트 편집이 활성화 되고 아이템 리스트와 입력값에 의한 선택이 모두 가능합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_item !== 'undefined') {
        $p.data.remove("dlt_item");
    }
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] 4개 Body 컬럼 모두 inputType=custom + typeGetter(con_inputType 값). typeGetter 가 설정되어 동작 전제(setCellInputTypeCustom=false) 충족. autoComplete 셀은 itemSet(라벨=지역명 / 값=코드) 로 아이템 리스트 제공. col2(인덱스 1) Column 은 setColumnVisible(1,false) 로 숨김 처리되어 columnInfo 인덱스가 숨김 Column 도 포함함을 확인할 수 있다.\n[절차] (필요시) con_inputType 선택 -> Target 재생성 -> rowIndex / columnInfo / disabled 선택 -> setCellDisableEdit 실행 -> 해당 셀 더블클릭(편집모드 진입) -> 값 입력 -> 다른 곳 클릭(포커스아웃).\n[확인] 편집 종료(onafteredit) 시 셀에 표시된 값이 리턴창에 출력된다. disabled=true 면 텍스트 편집이 비활성화되어 입력한 텍스트가 셀 값에 반영되지 않고(리스트 선택만 가능) 원래 값이 유지된다. disabled=false 면 입력한 값이 셀 값에 반영된다."', '', 'label1');

    // itemSet 바인딩용 DataList (autoComplete inputType 용 : col1=라벨(지역명), col2=값(코드))
    //  ※ createBasicDataList 는 col1~col4 스키마만 생성하므로 itemSet label/value 도 col1/col2 사용.
    $c.gcm.createBasicDataList('', '', 'dlt_item');
    dlt_item.setJSON([
        { "col1": "서울", "col2": "01" },
        { "col1": "부산", "col2": "02" },
        { "col1": "대구", "col2": "03" }
    ]);

    // 본문 데이터리스트 (autoComplete Cell 의 초기 표시값 : 아이템 값/라벨과 매칭)
    //  ※ Body custom 컬럼 id 가 dataList 컬럼(col1~col4)과 일치해야 셀 편집 가능(불일치 시 자동 readOnly).
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "01", "col2": "서울", "col3": "02", "col4": "부산" },
        { "col1": "02", "col2": "부산", "col3": "03", "col4": "대구" },
        { "col1": "03", "col2": "대구", "col3": "01", "col4": "서울" },
        { "col1": "01", "col2": "서울", "col3": "02", "col4": "부산" }
    ]);

    // target 생성
    //  4개 Body 컬럼 모두 inputType=custom + typeGetter 로 Cell inputType=con_inputType(기본 autoComplete) 구성.
    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" id="" ev:onafteredit="scwin.target1_onafteredit" style="width:680px;height:200px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="170" inputType="text" id="hcol1" value="col1 (custom)"></w2:column>';
    strTarget += '<w2:column width="170" inputType="text" id="hcol2" value="col2 (custom)"></w2:column>';
    strTarget += '<w2:column width="170" inputType="text" id="hcol3" value="col3 (custom)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="col4 (custom)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="170" inputType="custom" id="col1" dataList="col1" typeGetter="scwin.target1_typeGetter"></w2:column>';
    strTarget += '<w2:column width="170" inputType="custom" id="col2" dataList="col2" typeGetter="scwin.target1_typeGetter"></w2:column>';
    strTarget += '<w2:column width="170" inputType="custom" id="col3" dataList="col3" typeGetter="scwin.target1_typeGetter"></w2:column>';
    strTarget += '<w2:column width="*" inputType="custom" id="col4" dataList="col4" typeGetter="scwin.target1_typeGetter"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

    // col2(인덱스 1) Column 을 숨김 처리 : columnInfo 인덱스가 숨겨진 Column 도 포함함을 검증하기 위함.
    scwin.target1.setColumnVisible(1, false);
}



// 모든 custom 컬럼의 Cell inputType 을 con_inputType 선택값으로 구성한다.
//  @validation1 검증용 : inputType 이 autoComplete 일때만 setCellDisableEdit 가 동작,
//                        그 외(text/select) 이면 "Invalid cell input type" 로 미동작(false) 됨을 확인한다.
//  autoComplete 는 itemSet(아이템 리스트) 가 필수이므로 col1=라벨/col2=값 의 dlt_item 을 함께 전달한다.
//  ※ con_inputType 변경 후에는 'Target 재생성' 을 클릭해야 grid 가 새 inputType 으로 다시 그려진다.
scwin.target1_typeGetter = function (info) {
    let it = (typeof con_inputType !== 'undefined' && con_inputType.getValue()) ? con_inputType.getValue() : 'autoComplete';
    let ret = { id: 'cell_' + it + '_' + info.rowIndex + '_' + info.colIndex, inputType: it, options: {} };
    if (it === 'autoComplete' || it === 'select') {
        ret.itemSet = { nodeset: 'data:dlt_item', label: 'col1', value: 'col2' };
    }
    return ret;
};



// setCellDisableEdit 실행 : 특정 셀의 텍스트 편집 비활성화 여부를 설정 (3인자, 전제 미충족 시 false 반환)
//  적용 여부는 해당 셀을 더블클릭(편집모드) -> 값 입력 -> 포커스아웃 시 onafteredit 에서 표시값으로 확인한다.
scwin.btn_setCellDisableEdit_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());
    let columnInfo = Number(par_columnInfo.getValue());
    let disabledBool = (par_disabled.getValue() === "true");

    let ret = scwin.target1.setCellDisableEdit(rowIndex, columnInfo, disabledBool);

    wf_body_bottom.getObj("scwin").setReturnValue(
        "setCellDisableEdit(" + rowIndex + ", " + columnInfo + ", " + disabledBool + ")"
        + (ret === false ? " 미동작(false)" : " 적용")
        + " | 셀 더블클릭 -> 값 입력 -> 포커스아웃 시 셀 값 출력");
}



// 셀 편집모드 종료(포커스아웃) 시 발생. 셀에 표시된 값을 리턴창에 출력한다.
//  onafteredit @param : (rowIndex, columnIndex, value) 위치 인자. 표시값은 getCellDisplayData 로 조회.
//  disabled=true 면 텍스트 편집 비활성(리스트 선택만) 이라 입력 텍스트가 셀 값에 반영되지 않는다.
scwin.target1_onafteredit = function (rowIndex, columnIndex, value) {
    let shown = scwin.target1.getCellDisplayData(rowIndex, columnIndex);
    wf_body_bottom.getObj("scwin").setReturnValue(
        "셀(" + rowIndex + "," + columnIndex + ") 표시값 : " + shown);
}
